        }
        __syncthreads();

        // ── Step 3: Load B tile [BLOCK_N, MFMA_K/2] from global ──
        {
            const int total_bytes = BLOCK_N * MFMA_K / 2;
            const int bytes_per_thread = total_bytes / THREADS;
            #pragma unroll
            for (int i = 0; i < bytes_per_thread; i++) {
                int idx = tid * bytes_per_thread + i;
