                int local_m = my_row_start + mi;
                if (local_m >= BLOCK_M) continue;

                // Each lane handles 2 output columns
                int local_n = lane_id * 2;
                if (local_n >= BLOCK_N) continue;

                float sum0 = 0.0f, sum1 = 0.0f;

                for (int ki = 0; ki < MFMA_K; ki += 2) {
