                    uint8_t b_packed1 = smem_B_fp4[b_byte1];
                    float b00 = (float)((int8_t)((b_packed0 & 0xF) << 4) >> 4);
                    float b01 = (float)((int8_t)(b_packed0 & 0xF0) >> 4);
                    float b10 = (float)((int8_t)((b_packed1 & 0xF) << 4) >> 4);
                    float b11 = (float)((int8_t)(b_packed1 & 0xF0) >> 4);

