        // 256 threads -> ~4 groups per thread
        {
            const int total_groups = BLOCK_M * (MFMA_K / GROUP_SIZE);  // 32 * 2 = 64
            const int groups_per_thread = (total_groups + THREADS - 1) / THREADS;

            for (int g = 0; g < groups_per_thread; g++) {
