1	#!POPCORN leaderboard amd-mxfp4-mm
2	#!POPCORN gpu MI355X
3	
4	"""MXFP4 GEMM — Small-M tile: BLOCK_M=32, BLOCK_N=128, 4 waves (256 threads).
5	
6	Targets small-M shapes (M=4,16,32) where the 128x256 tile wastes most CUs.
7	A 32x128 tile creates ceil(M/32)*ceil(N/128) blocks → better occupancy for small M.
8	
9	Wave decomposition (4 waves, 256 threads):
10	  BLOCK_M=32, BLOCK_N=128 → 1 M-row × 4 N-cols of 32×32 MFMA tiles
11	  wave 0 → tile_n = bn + 0
12	  wave 1 → tile_n = bn + 32
13	  wave 2 → tile_n = bn + 64
14	  wave 3 → tile_n = bn + 96
15	  Each wave computes one 32×32 output tile (1 MFMA accumulator).
16	
17	Within each MFMA 32x32x64 call:
18	  - 32 rows of A: lanes 0-31 → row base, lanes 32-63 → row base (half=0 vs half=1 selects K half)
19	  - 32 rows of B (cols): lane & 31 selects the output column
20	"""
21	
22	import os
23	
24	os.environ["PYTORCH_ROCM_ARCH"] = "gfx950"
25	os.environ["CXX"] = "clang++"
26	
27	import torch
28	from torch.utils.cpp_extension import load_inline
29	from task import input_t, output_t
30	
31	HIP_SOURCE = r"""
32	#include <torch/extension.h>
33	#include <hip/hip_runtime.h>
34	#include <hip/hip_bf16.h>
35	
36	typedef int   a_reg_t __attribute__((ext_vector_type(8)));
37	typedef int   b_reg_t __attribute__((ext_vector_type(8)));
38	typedef float c_reg_t __attribute__((ext_vector_type(16)));
39	
40	#define BLOCK_M      32
41	#define BLOCK_N      128
42	#define TILE_K        64
43	#define TILE_K_BYTES  32
44	#define THREADS      256   // 4 waves x 64 threads
45	#define WAVESIZE      64
46	
47	// LDS: A=1024B, B=4096B, 2 slots = 10 KB total
48	#define LDS_A_BYTES  (BLOCK_M * TILE_K_BYTES)   // 1024
49	#define LDS_B_BYTES  (BLOCK_N * TILE_K_BYTES)   // 4096
50	
51	using i32x4        = int32_t  __attribute__((ext_vector_type(4)));
52	using as3_uint32_t = uint32_t __attribute__((address_space(3)));
53	using as3_uint32_p = as3_uint32_t*;
54	using as3_uint8_t  = uint8_t  __attribute__((address_space(3)));
55	using as3_uint8_p  = as3_uint8_t*;
56	
57	extern "C" __device__ void llvm_amdgcn_raw_buffer_load_lds(
58	    i32x4 rsrc, as3_uint32_p lds_ptr, int size,
59	    int voffset, int soffset, int offset, int aux)
60	    __asm("llvm.amdgcn.raw.buffer.load.lds");
61	
62	struct buffer_resource { uint64_t ptr; uint32_t range; uint32_t config; };
63	
64	__device__ __forceinline__ i32x4 make_srsrc(const void* ptr, uint32_t range) {
65	    buffer_resource r = {reinterpret_cast<uint64_t>(ptr), range, 0x00110000u};
66	    return *reinterpret_cast<const i32x4*>(&r);
67	}
68	
69	__device__ __forceinline__ int swizzle_byte_col(int row, int byte_col) {
70	    const int pair = (row >> 1) & 7;
71	    const int perm = pair ^ (((pair >> 1) ^ (pair >> 2)) & 1);
72	    return byte_col ^ (perm << 4);
73	}
74	
75	__device__ __forceinline__ uint32_t get_lds_byte_addr(const uint8_t* shared_ptr) {
76	    const as3_uint8_p p = reinterpret_cast<as3_uint8_p>(
77	        const_cast<uint8_t*>(shared_ptr));
78	    return static_cast<uint32_t>(reinterpret_cast<uintptr_t>(p));
79	}
80	
81	__device__ __forceinline__ void load_uint4_from_lds(
82	    const uint8_t* lds_base, int byte_off, void* dst
83	) {
84	    using u32x4_t = uint32_t __attribute__((ext_vector_type(4)));
85	    const uint32_t addr = get_lds_byte_addr(lds_base + byte_off);
86	    u32x4_t result;
87	    asm volatile("ds_read_b128 %0, %1\n" : "=v"(result) : "v"(addr) : "memory");
88	    *reinterpret_cast<u32x4_t*>(dst) = result;
89	}
90	
91	__device__ __forceinline__ void load_tile_global_to_lds(
92	    const uint8_t* __restrict__ global_base,
93	    uint8_t* __restrict__ lds_slot,
94	    int row_stride, int rows, int valid_rows, int global_row0,
95	    int tid, int num_threads
96	) {
97	    const int total_chunks = rows * (TILE_K_BYTES / 16);
98	    const uint32_t buf_range = (uint32_t)(rows * row_stride + TILE_K_BYTES);
99	    const i32x4 srsrc = make_srsrc(global_base, buf_range);
100	
101	    for (int chunk = tid; chunk < total_chunks; chunk += num_threads) {
102	        const int row       = chunk / (TILE_K_BYTES / 16);
103	        const int byte_col  = (chunk % (TILE_K_BYTES / 16)) * 16;
104	        const int swiz_col  = swizzle_byte_col(row, byte_col);
105	        const int lds_off   = row * TILE_K_BYTES + swiz_col;
106	        as3_uint32_p ldsp = reinterpret_cast<as3_uint32_p>(
107	            reinterpret_cast<as3_uint8_p>(lds_slot + lds_off));
108	        const int voffset = row * row_stride + byte_col;
109	        if (global_row0 + row < valid_rows) {
110	            llvm_amdgcn_raw_buffer_load_lds(srsrc, ldsp, 16, voffset, 0, 0, 0);
111	        } else {
112	            uint32_t* z = reinterpret_cast<uint32_t*>(lds_slot + lds_off);
113	            z[0] = z[1] = z[2] = z[3] = 0u;
114	        }
115	    }
116	}
117	
118	// ============================================================================
119	// 4-wave kernel: BLOCK_M=32, BLOCK_N=128
120	// Each wave owns 1 MFMA tile (32x32 output region):
121	//   wave 0→N cols [bn+0..31], wave 1→[bn+32..63],
122	//   wave 2→[bn+64..95],       wave 3→[bn+96..127]
123	// All 4 waves share the same BLOCK_M=32 row range.
124	// ============================================================================
125	__global__ __launch_bounds__(THREADS, 1)
126	void mxfp4_tile32x128(
127	    const uint8_t* __restrict__ A,
128	    const uint8_t* __restrict__ B,
129	    const uint8_t* __restrict__ As,
130	    const uint8_t* __restrict__ Bs,
131	    __hip_bfloat16* __restrict__ C,
132	    int M, int N, int K
133	) {
134	    const int tid    = threadIdx.x;
135	    const int waveid = tid / WAVESIZE;
136	    const int lane   = tid % WAVESIZE;
137	    const int half   = lane >> 5;   // 0=lanes 0-31, 1=lanes 32-63
138	
139	    const int bm = blockIdx.x * BLOCK_M;
140	    const int bn = blockIdx.y * BLOCK_N;
141	
142	    const int K_half  = K / 2;
143	    const int K_scale = K / 32;
144	    const int num_k   = K / TILE_K;
145	
146	    __shared__ uint8_t smem_A[2][LDS_A_BYTES];
147	    __shared__ uint8_t smem_B[2][LDS_B_BYTES];
148	
149	    // Each wave handles 1 N-tile of 32 columns
150	    const int tile_m = bm;                    // all waves: same M start
151	    const int tile_n = bn + waveid * 32;      // wave 0/1/2/3 → 0/32/64/96
152	
153	    // 1 accumulator per wave (32×32 MFMA output)
154	    c_reg_t c00 = {};
155	
156	    // Prologue: load K-tile 0
157	    load_tile_global_to_lds(
158	        A + bm * K_half, smem_A[0], K_half, BLOCK_M, M, bm, tid, THREADS);
159	    load_tile_global_to_lds(
160	        B + bn * K_half, smem_B[0], K_half, BLOCK_N, N, bn, tid, THREADS);
161	    asm volatile("s_waitcnt vmcnt(0)");
162	    __builtin_amdgcn_s_barrier();
163	
164	    for (int kt = 0; kt < num_k; kt++) {
165	        const int tic      = kt & 1;
166	        const int toc      = 1 - tic;
167	        const bool has_next = (kt + 1 < num_k);
168	
169	        // Use wave 0 as the load wave; waves 1-3 stall until load is done
170	        if (waveid != 0) {
171	            __builtin_amdgcn_s_barrier();
172	        }
173	
174	        if (has_next && waveid == 0) {
175	            __builtin_amdgcn_sched_barrier(0);
176	            const int next_k_off = (kt + 1) * TILE_K_BYTES;
177	
178	            // A: BLOCK_M=32, 2 chunks per row → 64 chunks × 16B = 1024B
179	            constexpr int a_chunks = BLOCK_M * (TILE_K_BYTES / 16);
180	            for (int c = lane; c < a_chunks; c += WAVESIZE) {
181	                const int row      = c / (TILE_K_BYTES / 16);
182	                const int byte_col = (c % (TILE_K_BYTES / 16)) * 16;
183	                const int swiz_col = swizzle_byte_col(row, byte_col);
184	                const int lds_off  = row * TILE_K_BYTES + swiz_col;
185	                as3_uint32_p ldsp = reinterpret_cast<as3_uint32_p>(
186	                    reinterpret_cast<as3_uint8_p>(smem_A[toc] + lds_off));
187	                const int global_row = bm + row;
188	                if (global_row < M) {
